function arrayToZod(
  schema: SchemaObject,
  opts: Required<TypeMapperOptions>,
  depth: number,
): string {
  if (!schema.items) {
    return "z.array(z.unknown())";
  }
  const itemType = schemaToZod(schema.items, opts, depth + 1);
  return `z.array(${itemType})`;
}

